package com.ncdex.order.service;import com.ncdex.order.client.InstrumentClient;import com.ncdex.order.kafka.OrderEventProducer;import com.ncdex.order.repository.OrderRepository;import com.ncdex.order.entity.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import java.util.*;import com.ncdex.order.dto.CreateOrderRequest;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class OrderManagementServiceTest{@Mock OrderRepository repo;@Mock InstrumentClient client;@Mock OrderEventProducer events;@InjectMocks OrderManagementService service;@Test void invalidTransitionIsRejected(){TradeOrder o=new TradeOrder();o.setStatus(OrderStatus.APPROVED);when(repo.findById(1L)).thenReturn(Optional.of(o));assertThrows(IllegalStateException.class,()->service.transition(1,"approve","admin",true));verify(repo,never()).save(any());}@Test void invalidQuantityIsRejectedBeforeExternalCall(){assertThrows(IllegalArgumentException.class,()->service.create(new CreateOrderRequest("GOLD-001",OrderType.BUY,0,15000,"bad"),"operator"));verifyNoInteractions(client,repo,events);}@Test void createsAndPublishesValidOrder(){when(client.get("GOLD-001")).thenReturn(Map.of("active",true));when(repo.save(any(TradeOrder.class))).thenAnswer(x->x.getArgument(0));var saved=service.create(new CreateOrderRequest("GOLD-001",OrderType.BUY,10,15000,"sample"),"operator");assertEquals(OrderStatus.SUBMITTED,saved.getStatus());assertEquals("operator",saved.getCreatedBy());verify(events).publish(saved);}@Test void inactiveInstrumentIsRejected(){when(client.get("GOLD-001")).thenReturn(Map.of("active",false));assertThrows(IllegalArgumentException.class,()->service.create(new CreateOrderRequest("GOLD-001",OrderType.BUY,1,100,"x"),"operator"));verify(repo,never()).save(any());}@Test void adminCanApproveSubmittedOrder(){TradeOrder o=new TradeOrder();o.setCreatedBy("operator");o.setStatus(OrderStatus.SUBMITTED);when(repo.findById(2L)).thenReturn(Optional.of(o));when(repo.save(o)).thenReturn(o);assertEquals(OrderStatus.APPROVED,service.transition(2,"approve","admin",true).getStatus());}@Test void operationsCannotApproveOrder(){TradeOrder o=new TradeOrder();o.setCreatedBy("operator");o.setStatus(OrderStatus.SUBMITTED);when(repo.findById(3L)).thenReturn(Optional.of(o));assertThrows(SecurityException.class,()->service.transition(3,"approve","operator",false));verify(repo,never()).save(any());}@Test void missingOrderIsReported(){when(repo.findById(77L)).thenReturn(Optional.empty());assertThrows(NoSuchElementException.class,()->service.get(77,"operator",false));}}
